```apex
public with sharing class LineItemDiscountHandler {

    /**
     * For every new line without an explicit Discount, apply the standard
     * discount for its product's family, as defined by PricingRules (owned
     * by the pricing team; we never duplicate its rules here).
     *
     * PricingRules.standardDiscountFor(Id) issues its own SOQL query
     * against Product2 every time it's called, which is not bulk-safe if
     * called once per line (or even once per distinct product) for large
     * CPQ batches. To stay within limits regardless of batch size, we:
     *   1. Collect the distinct Product2Ids that need a default discount.
     *   2. Query their Family values ourselves in a single bulk SOQL call.
     *   3. Call PricingRules.standardDiscountForFamily(family) - the
     *      family-based variant PricingRules already exposes - to get the
     *      actual discount. This still delegates 100% of the discount
     *      business logic to PricingRules; we only avoid re-querying
     *      Product2 redundantly, since we need the Family value anyway to
     *      call the bulk-safe entry point.
     *
     * This uses exactly one SOQL query no matter how many lines or
     * distinct products are in the batch (up to the 200-line CPQ limit
     * mentioned, and well beyond).
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        Set<Id> productIds = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        Map<Id, String> familyByProductId = new Map<Id, String>();
        for (Product2 p : [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]) {
            familyByProductId.put(p.Id, p.Family);
        }

        Map<String, Decimal> discountByFamily = new Map<String, Decimal>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                String family = familyByProductId.get(line.Product2Id);

                if (!discountByFamily.containsKey(family)) {
                    discountByFamily.put(
                        family,
                        PricingRules.standardDiscountForFamily(family)
                    );
                }

                line.Discount = discountByFamily.get(family);
            }
        }
    }
}
