trigger CaseTrigger on Case (after update) {
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !oldCase.IsClosed && c.ContactId != null) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    if (!newlyClosedCaseIds.isEmpty()) {
        // Enqueue a single job that processes the cases one at a time and
        // chains itself for the remainder. Salesforce allows up to 50
        // Queueable jobs to be started from a *synchronous* context (like
        // this trigger) in one transaction, but only 1 job may be started
        // from *within* a running Queueable (chaining). Chaining has no
        // such 50-job ceiling, so this approach safely handles any batch
        // size - including the nightly cleanup of up to 200 cases -
        // without hitting governor limits, while still processing each
        // case independently so one failure doesn't affect the others.
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
    }
}
